   DWORD dwCooltime, int splashcount, int hitcount, int range) */

bool __thiscall
TSkillUseInfo::UseSkill
          (TSkillUseInfo *this,bool isGrandMaster,DWORD vid,DWORD dwCooltime,int splashcount,
          int hitcount,int range)

{
  bool bVar1;
  DWORD DVar2;
  
                    /* Unresolved local var: DWORD dwCur@[DW_OP_reg2(EDX)] */
  this->isGrandMaster = isGrandMaster;
  DVar2 = get_dword_time();
  if ((this->bUsed == false) || (this->dwNextSkillUsableTime <= DVar2)) {
    this->bUsed = true;
    if (dwCooltime == 0) {
      this->dwNextSkillUsableTime = 0;
    }
    else {
      this->dwNextSkillUsableTime = dwCooltime + DVar2;
    }
    this->iHitCount = hitcount;
    this->iMaxHitCount = hitcount;
    this->iRange = range;
    sys_log(0,"__UseSkill NextUse %lu  current %lu cooltime %d hitcount %d/%d",
            this->dwNextSkillUsableTime,DVar2,dwCooltime,hitcount,hitcount);
    this->dwVID = vid;
    this->iSplashCount = splashcount;
    bVar1 = true;
  }
  else {
    sys_log(0,"cooltime is not over delta %lu",this->dwNextSkillUsableTime - DVar2);
    this->iHitCount = 0;
    bVar1 = false;
  }
  return bVar1;
}
